{"command": "create", "path": "/workspace/source/packages/privacy/src/erasure-policy.ts", "file_text": "import type { PoolClient } from 'pg';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  customer_id: string;
  status: string;
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ErasureResponse {
  id: string;
  customerId: string;
  status: ErasureStatus;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export function serializeErasureRequest(row: ErasureRequestRow): ErasureResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status as ErasureStatus,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.lastError ?? row.last_error ?? null,
  };
}

/** Stable error codes surfaced on failed requests. They never contain customer data. */
export const ERASURE_ERROR_CODES = [
  'object_storage_unavailable',
  'search_projection_unavailable',
  'cleanup_failed',
] as const;

export type ErasureErrorCode = (typeof ERASURE_ERROR_CODES)[number];

export function classifyErasureError(error: unknown, phase: 'documents' | 'search' | 'database'): string {
  if (phase === 'documents') return 'object_storage_unavailable';
  if (phase === 'search') return 'search_projection_unavailable';
  return 'cleanup_failed';
}

/**
 * Returns true when a deletion request has already been recorded for this
 * customer. Completed tombstones are permanent: delayed or replayed work must
 * not restore the customer's personal data once the tombstone exists.
 */
export async function erasureRequested(client: PoolClient, customerId: string): Promise<boolean> {
  const result = await client.query(
    `SELECT 1 FROM customers.erasure_requests WHERE customer_id=$1`,
    [customerId],
  );
  return Boolean(result.rowCount);
}

/**
 * Redacts the customer identity from a retained financial document (receipt or
 * invoice) while keeping every financial fact intact.
 */
export function scrubRetainedDocument(raw: string, customerId: string): string {
  const parsed: unknown = JSON.parse(raw);
  if (typeof parsed !== 'object' || parsed === null) throw new Error('document is not an object');
  const document = parsed as Record<string, unknown>;
  document.customer = null;
  return stringifyStable(document, customerId);
}

/** Removes identity-bearing keys from a customer import artifact. */
export function scrubCustomerImport(raw: string, customerId: string): string {
  const parsed: unknown = JSON.parse(raw);
  if (typeof parsed !== 'object' || parsed === null) throw new Error('document is not an object');
  const document = parsed as Record<string, unknown>;
  for (const key of ['email', 'name', 'phone', 'externalReference', 'customerId', 'notes']) {
    delete document[key];
  }
  return stringifyStable(document, customerId);
}

/** Rebuilds the document text, stripping any remaining mention of the customer identifier. */
function stringifyStable(document: Record<string, unknown>, customerId: string): string {
  return JSON.stringify(document).replaceAll(customerId, '');
}

/** Replaces customer identity inside retained payment snapshots without touching money fields. */
export function scrubCustomerSnapshot(snapshot: Record<string, unknown>): Record<string, unknown> {
  return { id: null, email: null, name: null, phone: null, external_reference: null, status: 'erased' };
}"}

