}

export function serializeErasureRequest(row: ErasureRequestRow): ErasureResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status as ErasureStatus,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error ?? null,
  };
}

export type ErasurePhase = 'documents' | 'search' | 'database';

const PHASE_ERROR_CODES: Record<ErasurePhase, string> = {
  documents: 'object_storage_unavailable',
  search: 'search_projection_unavailable',
  database: 'cleanup_failed',
};

/** Maps a failed cleanup step to a stable error code that contains no customer data. */
export function classifyErasureError(phase: ErasurePhase): string {
  return PHASE_ERROR_CODES[phase];
}

/**
 * Returns true when a deletion request has already been recorded for this
 * customer. Completed tombstones are permanent: delayed or replayed work must
 * not restore the customer's personal data once the tombstone exists.
 */
export async function erasureRequested(client: PoolClient, customerId: string): Promise<boolean> {
  const result = await client.query(
    `SELECT 1 FROM customers.erasure_requests WHERE customer_id=$1`,
    [customerId],
  );
  return Boolean(result.rowCount);
}

/**
 * Redacts the customer identity from a retained financial document (receipt or
 * invoice) while keeping every financial fact intact.
 */
export function scrubRetainedDocument(raw: string): string {
  const document = parseJsonObject(raw);
  document.customer = null;
  return JSON.stringify(document);
}

/** Removes identity-bearing fields from a customer import artifact. */
export function scrubCustomerImport(raw: string): string {
  const document = parseJsonObject(raw);
  for (const key of ['email', 'name', 'phone', 'externalReference', 'customerId', 'notes']) {
    delete document[key];
  }
  return JSON.stringify(document);
}

/**
 * Replaces customer identity inside retained payment snapshots without touching
 * the financial fields of the surrounding record.
 */
export function scrubCustomerSnapshot(): Record<string, unknown> {
  return { id: null, email: null, name: null, phone: null, external_reference: null, status: 'erased' };
}

function parseJsonObject(raw: string): Record<string, unknown> {
  const parsed: unknown = JSON.parse(raw);
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new Error('document is not an object');
  }
  return parsed as Record<string, unknown>;
}"}

{"command": "create", "path": "/workspace/source/packages/privacy/src/erasure-repository.ts", "file_text": "import type { PoolClient } from 'pg';
import { pool } from '../../database/src/pool.js';
import type { ErasureRequestRow } from './erasure-policy.js';

export class ErasureRepository {
  async findForCustomer(client: PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async create(client: PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id)
       VALUES($1,$2) RETURNING *`,
      [merchantId, customerId],
    );
    return result.rows[0]!;
  }

  async enqueue(client: PoolClient, requestId: string, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload)
       VALUES('privacy','erase_customer',$1,$2)`,
      [merchantId, { requestId, merchantId, customerId }],
    );
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  /** Claims a request for processing; completed requests are never reopened. */
  async markProcessing(requestId: string): Promise<boolean> {
    const result = await pool.query(
      `UPDATE customers.erasure_requests
       SET status='processing',attempts=attempts+1,last_error=NULL,updated_at=now()
       WHERE id=$1 AND status<>'completed'`,
      [requestId],
    );
    return Boolean(result.rowCount);
  }

  async markCompleted(requestId: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='completed',completed_at=now(),last_error=NULL,updated_at=now()
       WHERE id=$1 AND status<>'completed'`,
      [requestId],
    );
  }

  async markFailed(requestId: string, errorCode: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed',last_error=$2,updated_at=now()
       WHERE id=$1 AND status<>'completed'`,
      [requestId, errorCode],
    );
  }

  /**
   * Allows a merchant to re-drive a failed request without changing its ID or
   * redoing work that has already completed.
   */
  async revive(client: PoolClient, merchantId: string, requestId: string): Promise<boolean> {
    const result = await client.query(
      `UPDATE customers.erasure_requests
       SET status='pending',last_error=NULL,updated_at=now()
       WHERE merchant_id=$1 AND id=$2 AND status IN ('failed','pending')`,
      [merchantId, requestId],
    );
    return Boolean(result.rowCount);
  }
}"}

{"command": "create", "path": "/workspace/source/apps/customer-service/src/erasure-service.ts", "file_text": "import { createHash } from 'node:crypto';
import type pg from 'pg';
import { transaction } from '../../../packages/database/src/pool.js';
import { serializeErasureRequest, type ErasureResponse } from '../../../packages/privacy/src/erasure-policy.js';
import { ErasureRepository } from '../../../packages/privacy/src/erasure-repository.js';

export interface ErasureOutcome {
  status: number;
  body: ErasureResponse;
}

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async createRequest(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureOutcome> {
    return transaction(async (client) => {
      // A merchant must only be able to erase their own customers; unknown or
      // foreign customers are indistinguishable and change nothing.
      const customer = await client.query(
        `SELECT id FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      if (!customer.rowCount) {
        throw Object.assign(new Error('customer not found'), { statusCode: 404 });
      }

      const conflict = await this.reserveIdempotencyKey(client, merchantId, customerId, idempotencyKey);
      if (conflict) return conflict;

      const existing = await this.repository.findForCustomer(client, merchantId, customerId);
      if (existing) {
        if (existing.status === 'failed' || existing.status === 'processing') {
          await this.repository.revive(client, merchantId, existing.id);
          await this.repository.enqueue(client, existing.id, merchantId, customerId);
        }
        return { status: 202, body: serializeErasureRequest(await this.reload(client, merchantId, existing.id)) };
      }

      const created = await this.repository.create(client, merchantId, customerId);
      await this.repository.enqueue(client, created.id, merchantId, customerId);
      return { status: 202, body: serializeErasureRequest(created) };
    });
  }

  async getRequest(merchantId: string, requestId: string): Promise<ErasureResponse | undefined> {
    const row = await this.repository.find(merchantId, requestId);
    return row ? serializeErasureRequest(row) : undefined;
  }

  private async reload(client: pg.PoolClient, merchantId: string, requestId: string): Promise<NonNullable<Awaited<ReturnType<ErasureRepository['findForCustomer']>>> & { merchant_id?: string }> {
    const result = await client.query(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0]!;
  }

  private async reserveIdempotencyKey(
    client: pg.PoolClient, merchantId: string, customerId: string, key: string,
  ): Promise<ErasureOutcome | undefined> {
    const hash = createHash('sha256').update(JSON.stringify({ customerId })).digest('hex');
    const inserted = await client.query(
      `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
       VALUES($1,'erasure-request',$2,$3,now()+interval '24 hours') ON CONFLICT DO NOTHING`,
      [merchantId, key, hash],
    );
    if (inserted.rowCount) return undefined;
    const existing = await client.query<{ request_hash: string }>(
      `SELECT request_hash FROM operations.idempotency_keys
       WHERE merchant_id=$1 AND scope='erasure-request' AND key=$2 FOR UPDATE`,
      [merchantId, key],
    );
    if (existing.rows[0]?.request_hash !== hash) {
      throw Object.assign(new Error('idempotency key reused with a different request'), { statusCode: 409 });
    }
    return undefined;
  }
}"}

