import { serializeErasureRequest, type ErasureResponse } from '../../../packages/privacy/src/erasure-policy.js';
import { ErasureRepository } from '../../../packages/privacy/src/erasure-repository.js';

export interface ErasureOutcome {
  status: number;
  body: ErasureResponse;
}

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async createRequest(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureOutcome> {
    return transaction(async (client) => {
      // A merchant must only be able to erase their own customers; unknown or
      // foreign customers are indistinguishable and change nothing.
      const customer = await client.query(
        `SELECT id FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      if (!customer.rowCount) {
        throw Object.assign(new Error('customer not found'), { statusCode: 404 });
      }

      await this.checkIdempotencyKey(client, merchantId, customerId, idempotencyKey);

      const existing = await this.repository.findForCustomer(client, merchantId, customerId);
      if (existing) {
        // One request per customer: a repeat POST returns the same request ID
        // and never duplicates destructive work. A failed request is safe to
        // re-drive; a pending one is guaranteed to have a queued job.
        if (existing.status === 'failed') {
          await this.repository.revive(client, merchantId, existing.id);
          await this.repository.enqueue(client, existing.id, merchantId, customerId);
        } else if (existing.status === 'pending' && !(await this.hasQueuedJob(client, existing.id))) {
          await this.repository.enqueue(client, existing.id, merchantId, customerId);
        }
        return { status: 202, body: serializeErasureRequest(existing) };
      }

      const created = await this.repository.create(client, merchantId, customerId);
      await this.repository.enqueue(client, created.id, merchantId, customerId);
      return { status: 202, body: serializeErasureRequest(created) };
    });
  }

  async getRequest(merchantId: string, requestId: string): Promise<ErasureResponse | undefined> {
    const row = await this.repository.find(merchantId, requestId);
    return row ? serializeErasureRequest(row) : undefined;
  }

  private async hasQueuedJob(client: pg.PoolClient, requestId: string): Promise<boolean> {
    const result = await client.query(
      `SELECT 1 FROM operations.jobs
       WHERE queue='privacy' AND payload->>'requestId'=$1 AND status IN ('pending','retry','processing')`,
      [requestId],
    );
    return Boolean(result.rowCount);
  }

  private async checkIdempotencyKey(
    client: pg.PoolClient, merchantId: string, customerId: string, key: string,
  ): Promise<void> {
    const hash = createHash('sha256').update(JSON.stringify({ customerId })).digest('hex');
    const inserted = await client.query(
      `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
       VALUES($1,'erasure-request',$2,$3,now()+interval '24 hours') ON CONFLICT DO NOTHING`,
      [merchantId, key, hash],
    );
    if (inserted.rowCount) return;
    const existing = await client.query<{ request_hash: string }>(
      `SELECT request_hash FROM operations.idempotency_keys
       WHERE merchant_id=$1 AND scope='erasure-request' AND key=$2 FOR UPDATE`,
      [merchantId, key],
    );
    if (existing.rows[0]?.request_hash !== hash) {
      throw Object.assign(new Error('idempotency key reused with a different request'), { statusCode: 409 });
    }
  }
}"

