export interface CustomerIdentity {
  id: string;
  email: string | null;
  name: string | null;
  phone: string | null;
  externalReference: string | null;
}

export interface ManifestUpdate {
  objectKey: string;
  checksum: string;
}

/**
 * Performs the database portion of a customer deletion. Personal rows are
 * deleted outright; retained financial records are kept but de-identified.
 * Every statement is idempotent so the job can safely resume.
 */
export class PrivacyRepository {
  async getRequest(requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await this.pool().query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE id=$1`,
      [requestId],
    );
    return result.rows[0];
  }

  async loadIdentity(merchantId: string, customerId: string): Promise<CustomerIdentity | undefined> {
    const result = await this.pool().query<{ id: string; email: string; name: string; phone: string | null; external_reference: string }>(
      `SELECT id,email,name,phone,external_reference FROM customers.customers
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    const row = result.rows[0];
    if (!row) return undefined;
    return {
      id: row.id, email: row.email, name: row.name, phone: row.phone, externalReference: row.external_reference,
    };
  }

  identifiersFor(identity: CustomerIdentity | undefined, customerId: string): string[] {
    if (!identity) return [customerId];
    return [identity.id, identity.email, identity.name, identity.phone, identity.externalReference]
      .filter((value): value is string => Boolean(value));
  }

  async financialManifests(merchantId: string, customerId: string): Promise<Array<{ object_key: string; document_type: string }>> {
    const result = await this.pool().query<{ object_key: string; document_type: string }>(
      `SELECT object_key,document_type FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2 AND document_type IN ('receipt','invoice')`,
      [merchantId, customerId],
    );
    return result.rows;
  }

  async importManifests(merchantId: string): Promise<Array<{ id: string; object_key: string; metadata: Record<string, unknown> }>> {
    const result = await this.pool().query<{ id: string; object_key: string; metadata: Record<string, unknown> }>(
      `SELECT id,object_key,metadata FROM operations.document_manifests
       WHERE merchant_id=$1 AND document_type='customer_import'`,
      [merchantId],
    );
    return result.rows;
  }

  async applyCleanup(
    merchantId: string,
    customerId: string,
    identity: CustomerIdentity | undefined,
    manifestUpdates: ManifestUpdate[],
    deletedImportManifestIds: string[],
  ): Promise<void> {
    const identifiers = this.identifiersFor(identity, customerId);
    const anonymized = JSON.stringify(anonymizedSnapshot());
    await this.pool().query('BEGIN');
    const client = await this.takeClient();
    try {
      await this.scrubFinancialTables(client, merchantId, customerId, identifiers, anonymized);
      await this.deletePersonalTables(client, merchantId, customerId);
      await this.scrubOperationalJson(client, merchantId, customerId, identifiers);
      await this.applyManifestChanges(client, merchantId, customerId, manifestUpdates, deletedImportManifestIds);
      // The customer row goes last so referencing records are already gone.
      await client.query(`DELETE FROM customers.customers WHERE merchant_id=$1 AND id=$2`, [merchantId, customerId]);
      await client.query('COMMIT');
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  private async scrubFinancialTables(
    client: pg.PoolClient, merchantId: string, customerId: string, identifiers: string[], anonymized: string,
  ): Promise<void> {
    // Retained payments keep their financial meaning but drop the snapshot and
    // any identifying text.
    const payments = await client.query<{ id: string; description: string | null }>(
      `SELECT id,description FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    for (const payment of payments.rows) {
      await client.query(
        `UPDATE payments.payment_intents
         SET customer_id=NULL,customer_snapshot=$2::jsonb,description=$3,updated_at=now() WHERE id=$1`,
        [payment.id, anonymized, redactText(payment.description ?? '', identifiers)],
      );
    }
    await client.query(
      `UPDATE payments.payment_intents SET customer_snapshot=$2::jsonb
       WHERE merchant_id=$1 AND customer_snapshot::text LIKE $3`,
      [merchantId, anonymized, `%${customerId}%`],
    );

    const attempts = await client.query<{ id: string; request_payload: unknown; response_payload: unknown }>(
      `SELECT pa.id,pa.request_payload,pa.response_payload FROM payments.payment_attempts pa
       JOIN payments.payment_intents pi ON pi.id=pa.payment_intent_id
       WHERE pi.merchant_id=$1 AND (pi.customer_id=$2 OR pa.request_payload::text LIKE $3)`,
      [merchantId, customerId, `%${customerId}%`],
    );
    for (const attempt of attempts.rows) {
      await client.query(
        `UPDATE payments.payment_attempts SET request_payload=$2::jsonb,response_payload=$3::jsonb WHERE id=$1`,
        [
          attempt.id,
          JSON.stringify(scrubJsonPayload(attempt.request_payload, identifiers)),
          attempt.response_payload === null ? null : JSON.stringify(scrubJsonPayload(attempt.response_payload, identifiers)),
        ],
