}

const suffix = randomUUID().slice(0, 8);
const EMAIL = `replay.person+${suffix}@example.test`;
const NAME = `Replay Person ${suffix}`;

console.log('--- create customer ---');
const customer = (await api<{ id: string }>('/v1/customers', 'POST', {
  externalReference: `crm-replay-${suffix}`, email: EMAIL, name: NAME,
})).body;
console.log('customer', customer.id);

// Wait for projection of customer.created to land
await new Promise((r) => setTimeout(r, 3000));

// Verify projection exists before erasure
await search.indices.refresh({ index: 'payflow-customers-v1' });
const before = await search.search({ index: 'payflow-customers-v1', body: { query: { term: { customerId: customer.id } } } });
assert.equal((before.body.hits.total as { value: number }).value, 1, 'customer not projected before erasure');
const redisBefore = await redis.get(`merchant:${merchantId}:customer:${customer.id}`);
assert.ok(redisBefore, 'customer not in Redis cache before erasure');

console.log('--- request and complete erasure ---');
const created = await api<{ id: string }>(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `replay-erasure-${suffix}` });
assert.equal(created.status, 202);
let done = false;
for (let i = 0; i < 30; i += 1) {
  const got = await api<{ status: string }>(`/v1/erasure-requests/${created.body.id}`);
  if (got.body.status === 'completed') { done = true; break; }
  await new Promise((r) => setTimeout(r, 500));
}
assert.ok(done, 'erasure did not complete');
console.log('erasure completed');

// Verify projections are gone
await search.indices.refresh({ index: 'payflow-customers-v1' });
const afterErase = await search.search({ index: 'payflow-customers-v1', body: { query: { term: { customerId: customer.id } } } });
assert.equal((afterErase.body.hits.total as { value: number }).value, 0, 'OpenSearch still has customer after erasure');
assert.equal(await redis.get(`merchant:${merchantId}:customer:${customer.id}`), null, 'Redis still has customer after erasure');

console.log('--- replay customer.created event through Kafka ---');
// Simulate a replayed/delayed event that carries the old PII
const kafka = new Kafka({ clientId: 'replay-test', brokers: ['localhost:9092'] });
