  topic: 'payflow-domain-events-v1',
  messages: [{
    key: customer.id,
    value: JSON.stringify({
      eventId: randomUUID(),
      eventType: 'customer.created.v1',
      eventVersion: 1,
      occurredAt: new Date().toISOString(),
      aggregateType: 'customer',
      aggregateId: customer.id,
      merchantId,
      correlationId: randomUUID(),
      payload: { customerId: customer.id, email: EMAIL, name: NAME, phone: null, externalReference: `crm-replay-${suffix}`, metadata: {}, version: 1 },
    }),
  }],
});
await producer.disconnect();
console.log('replayed event sent');

// Wait for projection-worker to process (or block) the replayed event
await new Promise((r) => setTimeout(r, 5000));

console.log('--- verify replay did not restore PII ---');
await search.indices.refresh({ index: 'payflow-customers-v1' });
const afterReplay = await search.search({ index: 'payflow-customers-v1', body: { query: { term: { customerId: customer.id } } } });
assert.equal((afterReplay.body.hits.total as { value: number }).value, 0, 'REPLAY RESTORED OpenSearch PII');

const redisAfter = await redis.get(`merchant:${merchantId}:customer:${customer.id}`);
assert.equal(redisAfter, null, 'REPLAY RESTORED Redis PII');

const analytics = await pool.query(`SELECT count(*)::int AS n FROM operations.analytics_events WHERE customer_id=$1`, [customer.id]);
assert.equal(analytics.rows[0]!.n, 0, 'REPLAY RESTORED analytics PII');

const notif = await pool.query(`SELECT count(*)::int AS n FROM operations.notification_preferences WHERE customer_id=$1`, [customer.id]);
assert.equal(notif.rows[0]!.n, 0, 'REPLAY RESTORED notification preferences');

console.log('\nREPLAY GUARD CHECKS PASSED');
await pool.end();
await redis.quit();
process.exit(0);", "path": "/workspace/source/tmp-replay-guard.ts"}

