async function piiStillPresent(where: string): Promise<string[]> {
  const problems: string[] = [];
  const osDoc = await search.search({ index: 'payflow-customers-v1', body: { query: { term: { customerId: customer.id } } } });
  if ((osDoc.body.hits.total as { value: number }).value > 0) problems.push(`opensearch doc restored (${where})`);
  if (await redis.get(`merchant:${merchantId}:customer:${customer.id}`)) problems.push(`redis projection restored (${where})`);
  const analytics = await pool.query(`SELECT count(*)::int AS n FROM operations.analytics_events WHERE customer_id=$1`, [customer.id]);
  if (analytics.rows[0]!.n > 0) problems.push(`analytics events restored (${where})`);
  const notifications = await pool.query(`SELECT count(*)::int AS n FROM operations.notifications WHERE customer_id=$1`, [customer.id]);
  if (notifications.rows[0]!.n > 0) problems.push(`notifications restored (${where})`);
  for (const [table, expr] of [
    ['operations.email_deliveries', `destination||subject||text_body||html_body`],
    ['payments.payment_intents', `customer_snapshot::text||coalesce(description,'')`],
  ] as Array<[string, string]>) {
    const rows = await pool.query(
      `SELECT count(*)::int AS n FROM ${table} WHERE (${NEEDLES.map((_, i) => `(${expr}) LIKE $${i + 1}`).join(' OR ')}) AND (customer_id=$4 OR $4 IS NULL)`,
